 private async Task LoadAsync(){_lookups=await _service.GetLookupsAsync(_session.CompanyId,_session.BranchId);Bind(_account,_lookups.Accounts);Bind(_warehouse,_lookups.Warehouses);if(_lines.Columns["Product"] is DataGridViewComboBoxColumn productColumn)productColumn.DataSource=_lookups.Products.ToList();if(_edit is null)return;var detail=await _service.GetInvoiceDetailAsync(_edit.InvoiceId,_session.CompanyId)??throw new InvalidOperationException("Fatura bulunamadı.");_number.Text=detail.InvoiceNumber;_documentNumber.Text=detail.DocumentNumber??"";_dispatchNumber.Text=detail.DispatchNumber??"";if(detail.DispatchDate.HasValue){_dispatchDate.Checked=true;_dispatchDate.Value=detail.DispatchDate.Value;}_date.Value=detail.InvoiceDate;_due.Value=detail.DueDate;_currency.SelectedItem=detail.CurrencyCode;_rate.Value=detail.ExchangeRate;_description.Text=detail.Description??"";_account.SelectedValue=detail.AccountId;_type.SelectedIndex=detail.InvoiceType-1;foreach(var line in detail.Lines){int i=_lines.Rows.Add();var row=_lines.Rows[i];row.Cells["Product"].Value=line.ProductId;row.Cells["VariantId"].Value=line.VariantId;row.Cells["UnitId"].Value=line.UnitId;row.Cells["WarehouseId"].Value=line.WarehouseId;row.Cells["Quantity"].Value=line.Quantity;row.Cells["UnitPrice"].Value=line.UnitPrice;row.Cells["DiscountRate"].Value=line.DiscountRate;row.Cells["VatRate"].Value=line.VatRate;row.Cells["Description"].Value=line.Description;if(line.WarehouseId.HasValue)_warehouse.SelectedValue=(long)line.WarehouseId.Value;}bool editable=detail.Status==1;_lines.ReadOnly=!editable;_save.Enabled=editable;if(!editable)_message.Text="Onaylı veya iptal edilmiş belge salt okunur açıldı.";}
