internal sealed class FinanceEditorDialog:IAsyncDisposable
{
 private readonly KryptonForm _form=new();private readonly ITradeTransactionService _service;private readonly UserSessionData _session;private readonly FinanceListItem? _edit;
 private readonly KryptonComboBox _type=new(),_account=new(),_targetType=new(),_target=new(),_currency=new();private readonly KryptonTextBox _number=new(),_reference=new(),_description=new();
 private readonly KryptonDateTimePicker _date=new();private readonly KryptonNumericUpDown _amount=new(){DecimalPlaces=2,Maximum=100000000,ThousandsSeparator=true},_rate=new(){DecimalPlaces=4,Maximum=1000000,Value=1};private readonly Label _message=new();private TradeLookups _lookups=null!;
 public FinanceEditorDialog(ITradeTransactionService service,UserSessionData session,FinanceListItem? edit=null){_service=service;_session=session;_edit=edit;Build();}
 public async Task<DialogResult> ShowAsync(IWin32Window owner){await LoadAsync();return _form.ShowDialog(owner);}
 private void Build(){_form.Text=_edit is null?"R3 • Yeni Finans İşlemi":$"R3 • Finans Güncelle • {_edit.DocumentNumber}";_form.Icon=R3Branding.AppIcon;_form.StartPosition=FormStartPosition.CenterParent;_form.ClientSize=new Size(780,520);
  var t=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,Padding=new Padding(24),BackColor=Color.White};t.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));t.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));
  _type.DataSource=new[]{"Tahsilat","Ödeme","Kasa Giriş","Kasa Çıkış","Banka Giriş","Banka Çıkış"};_targetType.DataSource=new[]{"Kasa","Banka"};_currency.DataSource=new[]{"TRY","USD","EUR","GBP"};_targetType.SelectedIndexChanged+=(_,_)=>BindTarget();
  F(t,0,0,"İşlem Türü",_type);F(t,1,0,"Belge Numarası",_number);F(t,0,1,"İşlem Tarihi",_date);F(t,1,1,"Cari Hesap",_account);F(t,0,2,"Hesap Türü",_targetType);F(t,1,2,"Kasa / Banka",_target);F(t,0,3,"Tutar",_amount);F(t,1,3,"Para Birimi",_currency);F(t,0,4,"Döviz Kuru",_rate);F(t,1,4,"Referans",_reference);F(t,0,5,"Açıklama",_description,2);
  var footer=new Panel{Dock=DockStyle.Bottom,Height=58,Padding=new Padding(14,10,14,10),BackColor=Color.White};var save=R3Theme.CreatePrimaryButton(_edit is null?"İşlemi Kaydet":"İşlemi Güncelle");save.Dock=DockStyle.Right;save.Width=130;save.Click+=async(_,_)=>await SaveAsync();_message.Dock=DockStyle.Fill;_message.ForeColor=Color.Firebrick;footer.Controls.Add(_message);footer.Controls.Add(save);_form.Controls.Add(t);_form.Controls.Add(footer);}
 private async Task LoadAsync(){_lookups=await _service.GetLookupsAsync(_session.CompanyId,_session.BranchId);Bind(_account,_lookups.Accounts,true);BindTarget();if(_edit is not null){_number.Text=_edit.DocumentNumber;_date.Value=_edit.TransactionDate;_amount.Value=_edit.Amount;_currency.SelectedItem=_edit.CurrencyCode;_reference.Text=_edit.ReferenceNumber??"";_type.SelectedIndex=_edit.TransactionType switch{"Tahsilat"=>0,"Ödeme"=>1,"Kasa Giriş"=>2,"Kasa Çıkış"=>3,"Banka Giriş"=>4,_=>5};}}
