 private async Task SaveAsync(){try{if(_target.SelectedValue is null){_message.Text="Kasa veya banka hesabı zorunludur.";return;}int target=Convert.ToInt32(_target.SelectedValue,System.Globalization.CultureInfo.InvariantCulture);var x=new FinanceSaveRequest(_edit?.FinancialTransactionId,_session.CompanyId,_session.BranchId,_lookups.FiscalPeriodId,_session.UserId,(byte)(_type.SelectedIndex+1),_number.Text.Trim(),_date.Value,_account.SelectedValue is long a&&a>0?a:null,_targetType.SelectedIndex==0?target:null,_targetType.SelectedIndex==1?target:null,_currency.Text,_rate.Value,_amount.Value,_reference.Text,_description.Text);await _service.SaveFinanceAsync(x);_form.DialogResult=DialogResult.OK;_form.Close();}catch(Exception ex){_message.Text=ex.Message;}}
