}

internal sealed class PaymentAllocationDialog:IAsyncDisposable
{
 private readonly KryptonForm _form=new();private readonly ITradeTransactionService _service;private readonly UserSessionData _session;private readonly InvoiceListItem _invoice;
 private readonly KryptonComboBox _payment=new();private readonly KryptonNumericUpDown _amount=new(){DecimalPlaces=2,Maximum=100000000,ThousandsSeparator=true};private readonly Label _message=new();
 public PaymentAllocationDialog(ITradeTransactionService service,UserSessionData session,InvoiceListItem invoice){_service=service;_session=session;_invoice=invoice;Build();}
 public async Task<DialogResult> ShowAsync(IWin32Window owner){var all=await _service.GetFinanceTransactionsAsync(_session.CompanyId);string required=_invoice.InvoiceType is "Satış" or "Alış İade"?"Tahsilat":"Ödeme";var candidates=all.Where(x=>x.Status=="Onaylı"&&x.TransactionType==required&&x.AccountCode==_invoice.AccountCode).ToList();_payment.DataSource=candidates;_payment.DisplayMember=nameof(FinanceListItem.DocumentNumber);_payment.ValueMember=nameof(FinanceListItem.FinancialTransactionId);_amount.Value=Math.Max(0,_invoice.RemainingTotal);if(candidates.Count==0)_message.Text=$"Bu cari için onaylı {required.ToLowerInvariant()} bulunamadı.";return _form.ShowDialog(owner);}
 private void Build(){_form.Text=$"R3 • Ödeme Eşleştirme • {_invoice.InvoiceNumber}";_form.Icon=R3Branding.AppIcon;_form.StartPosition=FormStartPosition.CenterParent;_form.ClientSize=new Size(520,280);var t=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,Padding=new Padding(24),BackColor=Color.White};t.Controls.Add(new Label{Text=$"Kalan fatura tutarı: {_invoice.RemainingTotal:N2} {_invoice.CurrencyCode}",Dock=DockStyle.Fill,Font=new Font("Segoe UI",10,FontStyle.Bold)});t.Controls.Add(new Label{Text="Onaylı tahsilat / ödeme",Dock=DockStyle.Fill,ForeColor=R3Colors.MutedText});_payment.Dock=DockStyle.Fill;_payment.DropDownStyle=ComboBoxStyle.DropDownList;t.Controls.Add(_payment);t.Controls.Add(new Label{Text="Eşleştirilecek tutar",Dock=DockStyle.Fill,ForeColor=R3Colors.MutedText});_amount.Dock=DockStyle.Fill;t.Controls.Add(_amount);_message.Dock=DockStyle.Fill;_message.ForeColor=Color.Firebrick;t.Controls.Add(_message);var save=R3Theme.CreatePrimaryButton("Eşleştir");save.Dock=DockStyle.Bottom;save.Height=38;save.Click+=async(_,_)=>await SaveAsync();t.Controls.Add(save);_form.Controls.Add(t);}
 private async Task SaveAsync(){try{if(_payment.SelectedValue is null){_message.Text="Onaylı finans işlemi seçilmelidir.";return;}await _service.AllocatePaymentAsync(Convert.ToInt64(_payment.SelectedValue,System.Globalization.CultureInfo.InvariantCulture),_invoice.InvoiceId,_amount.Value,_session.UserId);_form.DialogResult=DialogResult.OK;_form.Close();}catch(Exception ex){_message.Text=ex.Message;}}
 public ValueTask DisposeAsync(){_form.Dispose();return ValueTask.CompletedTask;}
}
